CREATE OR REPLACE FUNCTION public.close_coach_account(p_coach_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_link record; v_asg record; v_fork_id uuid; v_transitioned int := 0; v_forked int := 0; BEGIN IF p_coach_id IS NULL THEN RAISE EXCEPTION 'Coach required'; END IF; FOR v_link IN SELECT client_id FROM public.coach_client_links WHERE coach_id = p_coach_id AND status = 'active' LOOP FOR v_asg IN SELECT pa.id AS assignment_id, pa.program_id, p.name, p.owner_id FROM public.program_assignments pa JOIN public.programs p ON p.id = pa.program_id WHERE pa.client_id = v_link.client_id AND pa.assigned_by = p_coach_id AND pa.status IN ('active', 'paused') LOOP IF v_asg.owner_id = p_coach_id THEN INSERT INTO public.programs (owner_id, name, description, duration_weeks) SELECT v_link.client_id, p.name, COALESCE(p.description, ''), p.duration_weeks FROM public.programs p WHERE p.id = v_asg.program_id RETURNING id INTO v_fork_id; INSERT INTO public.program_days (program_id, weekday, name, routine_id, order_index) SELECT v_fork_id, weekday, name, routine_id, order_index FROM public.program_days WHERE program_id = v_asg.program_id; INSERT INTO public.program_day_exercises (program_day_id, name, default_sets, default_reps, default_reps_min, default_rir, default_rest_seconds, default_weight_kg, order_index) SELECT nd.id, e.name, e.default_sets, e.default_reps, e.default_reps_min, e.default_rir, e.default_rest_seconds, e.default_weight_kg, e.order_index FROM public.program_days od JOIN public.program_days nd ON nd.program_id = v_fork_id AND nd.weekday = od.weekday AND nd.order_index = od.order_index JOIN public.program_day_exercises e ON e.program_day_id = od.id WHERE od.program_id = v_asg.program_id; UPDATE public.program_assignments SET program_id = v_fork_id, assigned_by = v_link.client_id, status = 'paused', updated_at = now() WHERE id = v_asg.assignment_id; v_forked := v_forked + 1; END IF; END LOOP; PERFORM public.transition_client_to_solo(p_coach_id, v_link.client_id); v_transitioned := v_transitioned + 1; END LOOP; RETURN jsonb_build_object('ok', true, 'transitioned', v_transitioned, 'forked', v_forked); END; $$; REVOKE ALL ON FUNCTION public.close_coach_account(uuid) FROM PUBLIC, anon, authenticated; GRANT EXECUTE ON FUNCTION public.close_coach_account(uuid) TO service_role;
